CREATE TABLE IF NOT EXISTS `AppointmentBill` (`id` VARCHAR(191) NOT NULL, `appointmentId` VARCHAR(191) NOT NULL, `snapshot` JSON NOT NULL, `total` DECIMAL(14,2) NOT NULL, `paid` DECIMAL(14,2) NOT NULL, `method` VARCHAR(30) NULL, `reference` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `AppointmentBill_appointmentId_key` (`appointmentId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;